import{_ as e,o as a,c as n,b6 as i}from"./chunks/framework.BUXTSoD9.js";const h=JSON.parse('{"title":"Project Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md"}'),l={name:"en/guide/introduction.md"};function r(d,t,o,s,g,p){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="project-introduction" tabindex="-1">Project Introduction <a class="header-anchor" href="#project-introduction" aria-label="Permalink to “Project Introduction”">​</a></h1><p>2025 is regarded by many as the first year of AI programming. More and more people are starting to use AI to write code, but what they produce often remains at the toy level — they don&#39;t know how to use Vibe Coding to organize their development workflow, which tools to choose, or what critical steps lie between a prototype and a live product.</p><p>We adopt a progressive <strong>three-stage practical learning path</strong>: a beginner onboarding stage where you quickly get started with AI programming through mini-games, Stage 1 where you master the Vibe Coding workflow and complete a web application prototype, Stage 2 where you learn full-stack development and deployment, and Stage 3 where you build cross-platform complex applications.</p><p>Each stage comes with a complete hands-on project, guiding you from toy to product through real-world challenges, ultimately equipping you with the ability to <strong>turn any idea into a working application</strong>.</p><p>We believe that by mastering Vibe Coding combined with systematic training, you alone can become a <strong>versatile developer who combines front-end and back-end development, AI capability integration, and product design</strong>.</p><p>This project is primarily designed for three types of learners:</p><ul><li><strong>Beginners (non-technical people / product and operations roles)</strong>: Help non-technical stakeholders and entry-level learners understand key concepts and complete their first AI-powered tool or product prototype.</li><li><strong>Junior to mid-level developers (students and developers with some foundation)</strong>: Systematically master Vibe Coding and native AI application development.</li><li><strong>Senior developers (companies and startups, open-source and independent developers)</strong>: Support teams and individuals in rapidly building, validating, and iterating on native AI applications.</li></ul><h2 id="📖-content-navigation" tabindex="-1">📖 Content Navigation <a class="header-anchor" href="#📖-content-navigation" aria-label="Permalink to “📖 Content Navigation”">​</a></h2><h3 id="general-appendix" tabindex="-1">General Appendix <a class="header-anchor" href="#general-appendix" aria-label="Permalink to “General Appendix”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/en/appendix/8-artificial-intelligence/ai-capability-dictionary.html">AI Capability Dictionary: Common AI core concepts, terminology, and scenario explanations</a></p><h3 id="stage-0-kindergarten" tabindex="-1">Stage 0: Kindergarten <a class="header-anchor" href="#stage-0-kindergarten" aria-label="Permalink to “Stage 0: Kindergarten”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/learning-map/">Beginner Onboarding: Learning Map</a></td><td style="text-align:left;">Overview of the complete learning path</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/ai-capabilities-through-games/">Beginner Onboarding: In the AI Era, If You Can Talk, You Can Code</a></td><td style="text-align:left;">Get an initial feel for AI programming capabilities through cases like Snake</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="stage-1-ai-product-manager" tabindex="-1">Stage 1: AI Product Manager <a class="header-anchor" href="#stage-1-ai-product-manager" aria-label="Permalink to “Stage 1: AI Product Manager”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/introduction-to-ai-ide/">1.2: Getting to Know AI IDE Tools</a></td><td style="text-align:left;">Learn to use an IDE, master the interface structure and efficient prompting</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/building-prototype/">1.3: Build a Prototype Hands-On</a></td><td style="text-align:left;">A complete loop from product analysis and breakdown to multi-page product prototype implementation</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/integrating-ai-capabilities/">1.4: Adding AI Capabilities to Your Prototype</a></td><td style="text-align:left;">Understand and complete API integration for common AI capabilities (text, image, video)</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/complete-project-practice/">1.5: Complete Project Practice</a></td><td style="text-align:left;">Simulate real-world scenarios, iterate based on user feedback, and complete a project showcase (includes a final assignment)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to “Appendix”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-a-product-thinking/">Appendix A: Product Thinking Supplement</a></td><td style="text-align:left;">A product thinking framework from idea evaluation to requirement breakdown and MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-b-common-errors/">Appendix B: Common Errors and Solutions</a></td><td style="text-align:left;">Common errors and troubleshooting methods in Vibe Coding</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-idea-sources/">Appendix: Where to Find Ideas</a></td><td style="text-align:left;">Discover niche directions from reference apps, trends, and VC lists</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-double-diamond/">Appendix: Double Diamond Model</a></td><td style="text-align:left;">Understand the complete rhythm of defining the problem first, then expanding into solution design</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-jobs-to-be-done/">Appendix: Jobs to Be Done</a></td><td style="text-align:left;">Use the JTBD method to understand what users truly want to accomplish</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-1/appendix-mom-test/">Appendix: The Mom Test Interview Method</a></td><td style="text-align:left;">A research method for validating needs through user interviews</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="stage-2-junior-to-mid-level-developer" tabindex="-1">Stage 2: Junior to Mid-level Developer <a class="header-anchor" href="#stage-2-junior-to-mid-level-developer" aria-label="Permalink to “Stage 2: Junior to Mid-level Developer”">​</a></h3><h4 id="front-end-section" tabindex="-1">Front-end Section <a class="header-anchor" href="#front-end-section" aria-label="Permalink to “Front-end Section”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;">Using Lovart to produce assets</td><td style="text-align:left;">Learn to use Lovart to batch-generate character, scene, and other visual assets, providing a foundation for UI design and front-end development</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Getting started with Figma and MasterGo</td><td style="text-align:left;">Use design tools to organize information architecture and page structure, laying the groundwork for front-end implementation</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Building your first modern application — UI design</td><td style="text-align:left;">Complete a component-based interface from design mockups, implementing the first link from design to code</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Designing pages and buttons following UI design specifications</td><td style="text-align:left;">Learn to use mainstream design specifications to organize page structure and button hierarchy, and leverage AI to generate design proposals</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-2/frontend/hogwarts-portraits/">Let&#39;s Build Hogwarts Portraits Together</a></td><td style="text-align:left;">Build a front-end application with AI capabilities from scratch, connecting design and development</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="back-end-development-section" tabindex="-1">Back-end Development Section <a class="header-anchor" href="#back-end-development-section" aria-label="Permalink to “Back-end Development Section”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;">What is an API</td><td style="text-align:left;">Understand HTTP interfaces and the request-response model, preparing for back-end integration and debugging</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-2/backend/database-supabase/">From Database to Supabase</a></td><td style="text-align:left;">Set up databases and APIs on Supabase, connecting data models to front-end pages</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Using large language models to assist in writing interface code and documentation</td><td style="text-align:left;">Use LLMs to help generate interface and database documentation and code, creating readable and testable back-end services</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Git workflows and Zeabur deployment</td><td style="text-align:left;">Manage code with Git workflows and deploy applications to Zeabur for going live</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Modern CLI development tools</td><td style="text-align:left;">Use CLI-based AI programming tools to accelerate development and debugging, forming a personal engineering workflow</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">How to integrate payment systems like Stripe</td><td style="text-align:left;">Integrate payment systems, completing the payment flow and basic settlement process</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Building your first modern application — full-stack application</td><td style="text-align:left;">Combine front-end, back-end, and payment modules to deliver a deployable full-stack web application</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Modern front-end component library + Trae in practice</td><td style="text-align:left;">Use a modern front-end component library with Trae to independently build a product with login/registration and payment support</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ai-capabilities-appendix" tabindex="-1">AI Capabilities Appendix <a class="header-anchor" href="#ai-capabilities-appendix" aria-label="Permalink to “AI Capabilities Appendix”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapter</th><th style="text-align:left;">Key Content</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/en/stage-2/ai-capabilities/dify-knowledge-base/">Getting Started with Dify and Knowledge Base Integration</a></td><td style="text-align:left;">Build tool-type products using Dify Workflow and basic RAG, creating a template for future application upgrades</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Learning to query the AI dictionary and integrate multi-modal APIs</td><td style="text-align:left;">Learn to find suitable models and APIs, and integrate text, image, and other multi-modal capabilities into your product</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="stage-3-senior-developer" tabindex="-1">Stage 3: Senior Developer <a class="header-anchor" href="#stage-3-senior-developer" aria-label="Permalink to “Stage 3: Senior Developer”">​</a></h3>',24)])])}const f=e(l,[["render",r]]);export{h as __pageData,f as default};
